syntax:
return_type function_name(parameter_type parameter1, parameter_type parameter2, ...){
  // Function body: statements to be executed
  return value; 
}

code_example:
#include <stdio.h>

int max(int a, int b) {
  return (a > b) ? a : b;
}

int main() {
  int p = 10, q = 5, r = 20, s = 15;
  int x = max(p + q, r + s);
  printf("The maximum value is: %d\n", x);
  return 0;
}
